export const MAX_BATCH_CALLS = 64;

// ---------- 普通交易分阶段签名收集（审批） ----------

/** 创建审批的入参：字段与普通交易提交一致（策略版本在创建时自动绑定，不由调用方提供） */
export type TransactionApprovalSubmission = TransactionSubmission;

/**
